fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (exposureTimeNs >= 250_000_000L) {
        // Slow shutter: show fractional seconds, e.g. "0.5s", "2s"
        val text = if (seconds % 1.0 == 0.0) {
            seconds.toInt().toString()
        } else {
            String.format("%.2f", seconds).trimEnd('0').trimEnd('.')
        }
        "${text}s"
    } else {
        // Fast shutter: show as 1/N, e.g. "1/30s", "1/1000s"
        "1/${(1_000_000_000.0 / exposureTimeNs).roundToInt()}s"
    }
}

