private const val TAG = "MainActivity"
private const val ACTION_TOGGLE_VIDEO = "com.pixelary.latent.TOGGLE_VIDEO"
private const val UI_UPDATE_INTERVAL_MS = 500L
private const val CAPTURE_THREAD_COUNT = 2
private const val JPEG_QUALITY = 95
private const val STILL_PREFIX = "LATENT_"
private const val VIDEO_PREFIX_NORMAL = "LATENT_VID_"
private const val VIDEO_PREFIX_COMPARISON = "LATENT_COMP_"
private const val GALLERY_RELATIVE_PATH = "DCIM/Camera"
private const val MAX_SHUTTER_NS = 1_000_000_000L / 30
