@Composable
private fun ShutterButton(
    isRecording: MutableState<Boolean>,
    isRecordingLocked: MutableState<Boolean>,
    lockDragOffset: MutableState<Float>,
    onToggleVideo: () -> Unit,
    onTakePhoto: () -> Unit
) {
    Box(
        modifier = Modifier
            .align(Alignment.BottomCenter)
            .padding(bottom = 64.dp),
        contentAlignment = Alignment.Center
    ) {
        if (isRecording.value && !isRecordingLocked.value) {
            val thresholdPx = with(LocalDensity.current) { LOCK_THRESHOLD.toPx() }
            val progress = (lockDragOffset.value / thresholdPx).coerceIn(0f, 1f)
            Box(
                modifier = Modifier
                    .size(80.dp * (1f + progress * 0.6f))
                    .background(Color.Red.copy(alpha = 0.2f + progress * 0.4f), CircleShape)
                    .border(
                        width = 2.dp,
                        color = Color.White.copy(alpha = 0.3f + progress * 0.5f),
                        shape = CircleShape
                    )
            )
        }

        Box(
            modifier = Modifier
                .size(if (isRecording.value) 72.dp else 80.dp)
                .background(if (isRecording.value) Color.Red else Color.White, CircleShape)
                .pointerInput(Unit) {
                    val thresholdPx = LOCK_THRESHOLD.toPx()
                    awaitPointerEventScope {
                        while (true) {
                            val down = awaitFirstDown()

                            if (isRecording.value) {
                                if (waitForUpOrCancellation() != null) onToggleVideo()
                                continue
                            }

                            val upChange = withTimeoutOrNull(viewConfiguration.longPressTimeoutMillis) {
                                while (true) {
                                    val pointer = awaitPointerEvent().changes.firstOrNull() ?: break
                                    if (!pointer.pressed) return@withTimeoutOrNull pointer
                                    pointer.consume()
                                }
                                null
                            }

                            if (upChange == null) {
                                if (!isRecording.value) onToggleVideo()
                                awaitLockDrag(thresholdPx, down.position.y, isRecordingLocked, lockDragOffset, onToggleVideo)
                            } else if (!isRecording.value) {
                                onTakePhoto()
                            }
                        }
                    }
                }
        ) {
            if (isRecordingLocked.value) {
                Icon(
                    Icons.Default.Lock,
                    contentDescription = "Locked",
                    tint = Color.White,
                    modifier = Modifier
                        .size(32.dp)
                        .align(Alignment.Center)
                )
            }
        }
    }
}

private suspend fun AwaitPointerEventScope.awaitLockDrag(
    thresholdPx: Float,
    downY: Float,
    isRecordingLocked: MutableState<Boolean>,
    lockDragOffset: MutableState<Float>,
    onToggleVideo: () -> Unit
) {
    while (true) {
        val pointer = awaitPointerEvent().changes.firstOrNull()
        if (pointer == null || !pointer.pressed) {
            if (!isRecordingLocked.value) onToggleVideo()
            lockDragOffset.value = 0f
            return
        }

        if (!isRecordingLocked.value) {
            val yOffset = downY - pointer.position.y
            lockDragOffset.value = yOffset.coerceAtLeast(0f)
            if (lockDragOffset.value >= thresholdPx) {
                isRecordingLocked.value = true
                lockDragOffset.value = 0f
            }
        }
        pointer.consume()
    }
}

