enum class FlashMode { AUTO, ON, OFF, TORCH }

class MainActivity : ComponentActivity() {
    private val volumeKeyEventFlow = MutableSharedFlow<Int>(extraBufferCapacity = 1)

    private val recordingReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            Log.d(TAG, "Received TOGGLE_VIDEO broadcast")
            if (intent?.action == ACTION_TOGGLE_VIDEO) {
                volumeKeyEventFlow.tryEmit(KeyEvent.KEYCODE_VOLUME_DOWN)
            }
        }
    }

    fun getRecordingReceiver(): BroadcastReceiver = recordingReceiver

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        enableEdgeToEdge()
        setContent {
            LatentTheme {
                MainScreen(volumeKeyEventFlow)
            }
        }
    }

    override fun onKeyDown(keyCode: Int, event: KeyEvent?): Boolean {
        val isShutterKey = keyCode == KeyEvent.KEYCODE_VOLUME_UP || keyCode == KeyEvent.KEYCODE_VOLUME_DOWN
        if (!isShutterKey) return super.onKeyDown(keyCode, event)
        volumeKeyEventFlow.tryEmit(keyCode)
        return true
    }
}

@Composable
fun MainScreen(volumeKeyEventFlow: SharedFlow<Int>) {
    val context = LocalContext.current
    val cameraProvider = remember { CameraProvider(context) }
    val sensorCapture = remember { SensorCapture(context) }
    val captureVideo = remember { CaptureVideo() }
    val glSurfaceView = remember { GLSurfaceView(context) }
    val perfOptimizer = remember { PerformanceOptimizer(context) }
    val locationTracker = remember { LocationTracker(context) }
    val captureExecutor = remember { Executors.newFixedThreadPool(CAPTURE_THREAD_COUNT) }
    val coroutineScope = rememberCoroutineScope()
    val state = remember { CameraUiState() }

    var hasCameraPermission by remember { mutableStateOf(hasRequiredPermissions(context)) }
    val permissionLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions()
    ) { permissions ->
        hasCameraPermission = REQUIRED_PERMISSIONS.all { permissions[it] == true }
    }

    LaunchedEffect(Unit) {
        if (!hasCameraPermission) permissionLauncher.launch(REQUESTED_PERMISSIONS)
    }

    val livePreview = remember {
        LivePreview(context).apply {
            bindPerfOptimizers(state, perfOptimizer, glSurfaceView)
        }
    }

    DisposableEffect(captureExecutor) {
        onDispose { captureExecutor.shutdown() }
    }

    LaunchedEffect(captureExecutor) {
        registerCaptureThreads(captureExecutor, state, perfOptimizer)
    }

    val updatePipelineSettings = {
        livePreview.setPipelineSettings(
            state.useSpatialDenoise, state.useFalseColor, state.highlightRecoveryEnabled
        )
    }

    val takePhoto = {
        val shutterStart = System.currentTimeMillis()
        locationTracker.updateLocation()
        val metadata = CaptureMetadata(
            iso = 0,
            exposureTimeNs = 0,
            focalLength = sensorCapture.getFocalLength(),
            aperture = sensorCapture.getAperture(),
            location = locationTracker.getLastLocation()
        )
        livePreview.requestCapture({ byteBuffer, width, height, timestamp, readbackTime, iso, shutter, meta, recycler ->
            captureExecutor.execute {
                val finalMeta = (meta ?: metadata).copy(iso = iso, exposureTimeNs = shutter)
                processCaptureInBackground(
                    context, byteBuffer, width, height, timestamp, readbackTime, shutterStart, finalMeta
                )
                recycler()
            }
        }, metadata)
        glSurfaceView.requestRender()
    }

    val saveCurrentVideoToGallery = {
        state.currentVideoFile?.let { videoFile ->
            val location = locationTracker.getLastLocation()
            captureExecutor.execute { saveVideoToGallery(context, videoFile, location) }
        }
        state.currentVideoFile = null
    }

    val toggleVideo = {
        if (state.isRecording) {
            captureVideo.stopRecording()
            val droppedFrames = livePreview.stopVideoRecording()
            sensorCapture.setAwbLock(false)
            state.isRecording = false
            state.isRecordingLocked = false
            state.lockDragOffset = 0f

            if (state.isComparisonMode) {
                livePreview.setComparisonMode(state.isComparisonEnabled)
                state.isComparisonMode = false
            }
            if (droppedFrames > 0) {
                Toast.makeText(
                    context,
                    "Recording finished with $droppedFrames dropped frames",
                    Toast.LENGTH_LONG
                ).show()
            }
            saveCurrentVideoToGallery()
        } else {
            val prefix = if (state.isComparisonEnabled) VIDEO_PREFIX_COMPARISON else VIDEO_PREFIX_NORMAL
            state.currentVideoFile = File(
                context.getExternalFilesDir(null),
                "$prefix${System.currentTimeMillis()}.mp4"
            )
            state.currentVideoFile?.let { videoFile ->
                if (state.isComparisonEnabled) {
                    state.isComparisonMode = true
                    livePreview.setComparisonMode(true)
                }
                livePreview.startVideoRecording(captureVideo, videoFile, locationTracker.getLastLocation())
                state.isRecording = true
                sensorCapture.setAwbLock(true)
                state.recordingStartTime = System.currentTimeMillis()

                coroutineScope.launch {
                    while (state.isRecording) {
                        state.recordingDuration =
                            ((System.currentTimeMillis() - state.recordingStartTime) / 1000).toInt()
                        delay(1000)
                    }
                }
            }
        }
    }

    LaunchedEffect(volumeKeyEventFlow) {
        volumeKeyEventFlow.collect { keyCode ->
            when (keyCode) {
                KeyEvent.KEYCODE_VOLUME_UP -> takePhoto()
                KeyEvent.KEYCODE_VOLUME_DOWN -> toggleVideo()
            }
        }
    }

    val lifecycleOwner = LocalLifecycleOwner.current
    var lifecycleEvent by remember { mutableStateOf(Lifecycle.Event.ON_ANY) }
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event -> lifecycleEvent = event }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }

    LaunchedEffect(
        hasCameraPermission,
        state.selectedCameraId,
        state.selectedPhysicalId,
        lifecycleEvent,
        state.rawPreviewSurface
    ) {
        if (!hasCameraPermission || state.selectedCameraId.isEmpty()) return@LaunchedEffect

        when (lifecycleEvent) {
            Lifecycle.Event.ON_PAUSE, Lifecycle.Event.ON_STOP -> {
                unregisterToggleVideoReceiver(context)
                if (state.isRecording) {
                    captureVideo.stopRecording()
                    livePreview.stopVideoRecording()
                    state.isRecording = false
                    saveCurrentVideoToGallery()
                }
                sensorCapture.closeCamera()
                livePreview.clearPendingImage()
                livePreview.cleanup()
                glSurfaceView.onPause()
                state.openedCameraKey = ""
                state.lastOpenedSurface = null
                state.rawPreviewSurface = null
            }
            Lifecycle.Event.ON_RESUME, Lifecycle.Event.ON_START -> {
                registerToggleVideoReceiver(context)
                glSurfaceView.onResume()
                val cameraKey = cameraKeyOf(state.selectedCameraId, state.selectedPhysicalId)
                val surfaceReady = state.rawPreviewSurface != null
                val needsReopen = state.openedCameraKey != cameraKey || state.lastOpenedSurface != state.rawPreviewSurface
                if (surfaceReady && needsReopen) {
                    openSelectedCamera(context, sensorCapture, livePreview, perfOptimizer, state)
                }
            }
            else -> Unit
        }
    }

    LaunchedEffect(hasCameraPermission) {
        if (!hasCameraPermission) return@LaunchedEffect
        state.cameras = cameraProvider.getAvailableCameras()
        val first = state.cameras.firstOrNull() ?: return@LaunchedEffect
        if (state.selectedCameraId.isEmpty()) {
            state.selectedCameraId = first.id
            state.selectedPhysicalId = state.cameras.find { it.zoomLabel == "1x" }?.physicalId ?: first.physicalId
        }
    }

    CameraScreen(
        state = state,
        livePreview = livePreview,
        glSurfaceView = glSurfaceView,
        sensorCapture = sensorCapture,
        hasCameraPermission = hasCameraPermission,
        onToggleVideo = toggleVideo,
        onTakePhoto = takePhoto,
        onShowSettings = { state.showSettings = true },
        updatePipelineSettings = updatePipelineSettings
    )
}

private fun hasRequiredPermissions(context: Context): Boolean =
    REQUIRED_PERMISSIONS.all {
        ContextCompat.checkSelfPermission(context, it) == PackageManager.PERMISSION_GRANTED
    }

private fun registerToggleVideoReceiver(context: Context) {
    val activity = context.findActivity() as? MainActivity ?: return
    ContextCompat.registerReceiver(
        context,
        activity.getRecordingReceiver(),
        IntentFilter(ACTION_TOGGLE_VIDEO),
        ContextCompat.RECEIVER_NOT_EXPORTED
    )
}

private fun unregisterToggleVideoReceiver(context: Context) {
    val activity = context.findActivity() as? MainActivity ?: return
    runCatching { context.unregisterReceiver(activity.getRecordingReceiver()) }
}

private fun cameraKeyOf(cameraId: String, physicalId: String?): String = "$cameraId:${physicalId ?: ""}"

private suspend fun registerCaptureThreads(
    executor: ExecutorService,
    state: CameraUiState,
    perfOptimizer: PerformanceOptimizer
) {
    val tids = mutableListOf<Int>()
    val latch = CountDownLatch(CAPTURE_THREAD_COUNT)
    repeat(CAPTURE_THREAD_COUNT) {
        executor.execute {
            synchronized(tids) { tids.add(Process.myTid()) }
            latch.countDown()
        }
    }
    withContext(Dispatchers.IO) { latch.await() }

    if (tids.isEmpty()) return
    state.activeThreads = (state.activeThreads + tids).distinct().toIntArray()
    perfOptimizer.updateThreads(state.activeThreads)
    Log.d(TAG, "Capture threads added to ADPF: ${tids.joinToString()}")
}

private fun LivePreview.bindPerfOptimizers(
    state: CameraUiState,
    perfOptimizer: PerformanceOptimizer,
    glSurfaceView: GLSurfaceView
) {
    fun registerThread(tid: Int) {
        if (state.activeThreads.contains(tid)) return
        Process.setThreadPriority(tid, Process.THREAD_PRIORITY_URGENT_DISPLAY)
        state.activeThreads = state.activeThreads + tid
        perfOptimizer.updateThreads(state.activeThreads)
    }

    setOnFrameProcessedListener { timeMs ->
        perfOptimizer.reportActualWorkDuration(timeMs * 1_000_000L)
        val now = System.currentTimeMillis()
        if (now - state.lastProcessingUiUpdateTime > UI_UPDATE_INTERVAL_MS) {
            state.processingTimeMs = timeMs
            state.lastProcessingUiUpdateTime = now
        }
    }
    setOnVideoThreadIdAvailableListener { tid -> registerThread(tid) }
    setOnGlThreadIdAvailableListener { tid -> registerThread(tid) }
    setOnIspThreadIdAvailableListener { tid -> registerThread(tid) }
    setOnRawPreviewSurfaceReadyListener { surface -> state.rawPreviewSurface = surface }
    setRequestRenderCallback { glSurfaceView.requestRender() }
}

private fun openSelectedCamera(
    context: Context,
    sensorCapture: SensorCapture,
    livePreview: LivePreview,
    perfOptimizer: PerformanceOptimizer,
    state: CameraUiState
) {
    val selectedCameraId = state.selectedCameraId
    val selectedPhysicalId = state.selectedPhysicalId
    val rawPreviewSurface = state.rawPreviewSurface

    sensorCapture.closeCamera()
    livePreview.resetForCameraSwitch()

    sensorCapture.setOnSensorImageAvailableListener(object : SensorCapture.OnSensorImageAvailableListener {
        override fun onSensorImageAvailable(reader: ImageReader) {
            try {
                reader.acquireNextImage()?.let { livePreview.updateSensorImage(it) }
            } catch (e: Exception) {
                Log.e(TAG, "live Error acquiring image", e)
            }
        }
    })

    sensorCapture.setOnMetadataAvailableListener(object : SensorCapture.OnMetadataAvailableListener {
        override fun onMetadataAvailable(
            iso: Int,
            exposureTimeNs: Long,
            dynamicBlackLevel: FloatArray?,
            awbGains: FloatArray?,
            colorMatrix: FloatArray?,
            intrinsics: FloatArray?,
            flickerHz: Int
        ) {
            livePreview.setIso(iso)
            livePreview.setExposureTime(exposureTimeNs)
            snapExposureToFlicker(sensorCapture, state, flickerHz)

            val now = System.currentTimeMillis()
            if (now - state.lastMetadataUiUpdateTime > UI_UPDATE_INTERVAL_MS) {
                state.currentIso = iso
                state.currentExposureTimeNs = exposureTimeNs
                state.lastMetadataUiUpdateTime = now
            }

            livePreview.setBlackLevelPattern(dynamicBlackLevel ?: DEFAULT_BLACK_LEVEL_PATTERN)
            if (awbGains != null && !state.isRecording) {
                livePreview.setWbGains(
                    maxOf(MIN_WB_GAIN, awbGains[0]),
                    maxOf(MIN_WB_GAIN, awbGains[1]),
                    maxOf(MIN_WB_GAIN, awbGains[2])
                )
            }
            colorMatrix?.let { livePreview.setColorMatrix(it) }
        }
    })

    val effectiveId = selectedPhysicalId ?: selectedCameraId
    val cameraInfo = state.cameras.find {
        it.id == selectedCameraId && it.physicalId == selectedPhysicalId
    }

    livePreview.apply {
        setIsMirrored(cameraInfo?.facing == CameraCharacteristics.LENS_FACING_FRONT)
        setSensorOrientation(sensorCapture.getSensorOrientation(effectiveId))
        setCfaPattern(sensorCapture.getCfaPattern(effectiveId))
        setBlackLevelPattern(sensorCapture.getBlackLevelPattern(effectiveId))
        setWhiteLevel(sensorCapture.getWhiteLevel(effectiveId, selectedCameraId).toFloat())
        setDistortion(sensorCapture.getLensDistortion(effectiveId))
        setBlackLevelOffset(0.0f)
        setAutoLevelsMode(state.autoLevelsMode)
        setShowHistogram(state.showHistogram)
        setLogRange(state.logRange)
        setPipelineSettings(state.useSpatialDenoise, state.useFalseColor, state.highlightRecoveryEnabled)
    }
    cameraInfo?.maxPreviewResolution?.let { livePreview.setRawPreviewResolution(it.width, it.height) }

    sensorCapture.openCamera(selectedCameraId, selectedPhysicalId, rawPreviewSurface)
    state.openedCameraKey = cameraKeyOf(selectedCameraId, selectedPhysicalId)
    state.lastOpenedSurface = rawPreviewSurface

    state.currentIsoRange = sensorCapture.getIsoRange()
    val rawShutterRange = sensorCapture.getShutterRange()
    state.currentShutterRange =
        android.util.Range(rawShutterRange.lower, minOf(rawShutterRange.upper, MAX_SHUTTER_NS))
    state.aeCompensationRange = sensorCapture.getExposureCompensationRange()
    state.aeCompensationStep = sensorCapture.getExposureCompensationStep()
    sensorCapture.apply {
        setManualIso(state.manualIso)
        setManualExposureTime(state.manualExposureTimeNs)
        setExposureCompensation(state.aeCompensation)
        setAeLock(state.lockExposure)
        setUseOis(state.useOis)
    }

    context.findActivity()?.window?.let { window ->
        perfOptimizer.enableSustainedPerformanceMode(window)
        perfOptimizer.startPerformanceSession(state.activeThreads)
    }
}

private fun snapExposureToFlicker(sensorCapture: SensorCapture, state: CameraUiState, flickerHz: Int) {
    if (flickerHz == state.currentFlickerHz) return
    state.currentFlickerHz = flickerHz
    if (flickerHz <= 0 || state.manualExposureTimeNs <= 0L) return

    val period = if (flickerHz == 50) FLICKER_PERIOD_50HZ_NS else FLICKER_PERIOD_60HZ_NS
    val snapped = max(1L, (state.manualExposureTimeNs.toDouble() / period).roundToLong() * period)
    if (snapped != state.manualExposureTimeNs) {
        state.manualExposureTimeNs = snapped
        sensorCapture.setManualExposureTime(snapped)
    }
}

@Composable
private fun CameraScreen(
    state: CameraUiState,
    livePreview: LivePreview,
    glSurfaceView: GLSurfaceView,
    sensorCapture: SensorCapture,
    hasCameraPermission: Boolean,
    onToggleVideo: () -> Unit,
    onTakePhoto: () -> Unit,
    onShowSettings: () -> Unit,
    updatePipelineSettings: () -> Unit
) {
    Scaffold(modifier = Modifier.fillMaxSize()) {
        BoxWithConstraints(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black)
        ) {
            if (!hasCameraPermission) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text(text = "Camera permission required")
                }
                return@BoxWithConstraints
            }

            val imageHeight = maxWidth * ASPECT_RATIO_4_3
            val letterbox = (maxHeight * 0.9f - imageHeight).coerceAtLeast(0.dp)
            val imageBottomFromTop = maxHeight * 0.1f + letterbox * 0.1f + imageHeight

            PreviewSurface(glSurfaceView = glSurfaceView, livePreview = livePreview)

            Column(
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .padding(top = 64.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    text = "ISO ${state.currentIso}  |  ${formatShutterSpeed(state.currentExposureTimeNs)}",
                    modifier = Modifier.padding(top = 4.dp),
                    color = Color.White,
                    style = MaterialTheme.typography.bodyMedium
                )
                if (state.isShowingRawPreview) {
                    Text(
                        text = "Google Camera",
                        modifier = Modifier.padding(top = 16.dp),
                        color = Color.White.copy(alpha = 0.5f),
                        style = MaterialTheme.typography.labelLarge
                    )
                }
            }

            if (state.showDebugData) {
                DebugOverlay(
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(top = 64.dp, end = 16.dp),
                    processingTimeMs = state.processingTimeMs
                )
            }

            ShutterButton(
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .padding(bottom = 64.dp),
                isRecording = state.isRecordingState,
                isRecordingLocked = state.isRecordingLockedState,
                lockDragOffset = state.lockDragOffsetState,
                onToggleVideo = onToggleVideo,
                onTakePhoto = onTakePhoto
            )

            if (state.isRecording) {
                RecordingIndicator(
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .padding(top = 104.dp),
                    durationSeconds = state.recordingDuration
                )
            }

            IconButton(
                onClick = onShowSettings,
                modifier = Modifier
                    .align(Alignment.BottomStart)
                    .padding(start = 24.dp, bottom = 64.dp)
                    .size(64.dp)
                    .background(Color.Black.copy(alpha = 0.5f), CircleShape)
            ) {
                Icon(
                    Icons.Default.Settings,
                    contentDescription = "Settings",
                    tint = Color.White,
                    modifier = Modifier.size(32.dp)
                )
            }

            Box(
                modifier = Modifier
                    .align(Alignment.BottomEnd)
                    .padding(end = 24.dp, bottom = 24.dp)
            ) {
                BuildTimerText()
            }

            RawPreviewButton(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(top = imageBottomFromTop - 80.dp, end = 16.dp),
                onPreviewVisibilityChanged = { visible ->
                    state.isShowingRawPreview = visible
                    livePreview.setShowRawPreview(visible)
                }
            )

            ZoomSlider(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(end = 16.dp, top = 40.dp),
                imageWidth = maxWidth,
                zoom = state.zoomValue,
                onZoomChanged = {
                    state.zoomValue = it
                    livePreview.setMagnification(it)
                }
            )

            LensSelectorRow(
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .padding(top = imageBottomFromTop - 80.dp),
                cameras = state.cameras,
                selectedCameraId = state.selectedCameraId,
                selectedPhysicalId = state.selectedPhysicalId,
                onSelect = { cameraId, physicalId ->
                    state.selectedCameraId = cameraId
                    state.selectedPhysicalId = physicalId
                    state.zoomValue = 1f
                    livePreview.setMagnification(1f)
                }
            )

            if (state.showSettings) {
                SettingsPanel(
                    state = state,
                    sensorCapture = sensorCapture,
                    livePreview = livePreview,
                    updatePipelineSettings = updatePipelineSettings,
                    onDismiss = { state.showSettings = false }
                )
            }
        }
    }
}

@Composable
private fun PreviewSurface(glSurfaceView: GLSurfaceView, livePreview: LivePreview) {
    Column(modifier = Modifier.fillMaxSize()) {
        Spacer(modifier = Modifier.fillMaxHeight(0.1f))
        AndroidView(
            modifier = Modifier.fillMaxSize(),
            factory = {
                glSurfaceView.apply {
                    setEGLContextClientVersion(3)
                    setEGLConfigChooser { egl, display ->
                        val attribList = intArrayOf(
                            android.opengl.EGL14.EGL_RED_SIZE, 8,
                            android.opengl.EGL14.EGL_GREEN_SIZE, 8,
                            android.opengl.EGL14.EGL_BLUE_SIZE, 8,
                            android.opengl.EGL14.EGL_ALPHA_SIZE, 8,
                            android.opengl.EGL14.EGL_RENDERABLE_TYPE, android.opengl.EGL14.EGL_OPENGL_ES2_BIT,
                            android.opengl.EGLExt.EGL_RECORDABLE_ANDROID, 1,
                            android.opengl.EGL14.EGL_NONE
                        )
                        val configs = arrayOfNulls<javax.microedition.khronos.egl.EGLConfig>(1)
                        val numConfigs = IntArray(1)
                        egl.eglChooseConfig(display, attribList, configs, 1, numConfigs)
                        configs[0] ?: throw RuntimeException("No recordable EGL config found")
                    }
                    setRenderer(livePreview)
                    renderMode = GLSurfaceView.RENDERMODE_WHEN_DIRTY
                }
            }
        )
    }
}

