@Composable
private fun LensChip(label: String, selected: Boolean, onClick: () -> Unit) {
    Surface(
        onClick = onClick,
        color = if (selected) MaterialTheme.colorScheme.primary else Color.Transparent,
        shape = CircleShape,
        modifier = Modifier.size(40.dp)
