fun processCaptureInBackground(
    context: Context,
    byteBuffer: ByteBuffer,
    width: Int,
    height: Int,
    timestamp: Long,
    readbackTime: Long,
    shutterStartTime: Long,
    metadata: CaptureMetadata
) {
    try {
        val t0 = System.currentTimeMillis()
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        byteBuffer.rewind()
        bitmap.copyPixelsFromBuffer(byteBuffer)
        val t1 = System.currentTimeMillis()

        saveBitmapToGallery(context, bitmap, metadata, shutterStartTime, readbackTime, t1 - t0)
        bitmap.recycle()

        val t2 = System.currentTimeMillis()
        Log.d(
            TAG,
            "[PERF_CAPTURE] res=${width}x${height} total=${t2 - shutterStartTime}ms " +
                "wait=${t0 - shutterStartTime}ms copy=${t1 - t0}ms write=${t2 - t1}ms readback=${readbackTime}ms"
        )
    } catch (e: Exception) {
        Log.e(TAG, "capture Background capture failed: ${e.message}", e)
    }
}

fun saveBitmapToGallery(
    context: Context,
    bitmap: Bitmap,
    metadata: CaptureMetadata,
    shutterStart: Long,
    readbackTime: Long,
    bitmapTime: Long
) {
    val now = System.currentTimeMillis()
    val contentValues = ContentValues().apply {
        put(MediaStore.MediaColumns.DISPLAY_NAME, "$STILL_PREFIX${metadata.timestamp}.jpg")
        put(MediaStore.MediaColumns.MIME_TYPE, "image/jpeg")
        put(MediaStore.MediaColumns.RELATIVE_PATH, GALLERY_RELATIVE_PATH)
        put(MediaStore.MediaColumns.DATE_TAKEN, metadata.timestamp)
        put(MediaStore.MediaColumns.DATE_ADDED, now / 1000)
        put(MediaStore.MediaColumns.DATE_MODIFIED, now / 1000)
        put(MediaStore.MediaColumns.WIDTH, bitmap.width)
        put(MediaStore.MediaColumns.HEIGHT, bitmap.height)
        put(MediaStore.Images.ImageColumns.ORIENTATION, 0)
        put(MediaStore.MediaColumns.IS_PENDING, 1)
    }

    val imageUri = context.contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues)
        ?: return

    try {
        val tStart = System.currentTimeMillis()
        context.contentResolver.openOutputStream(imageUri)?.use { outputStream ->
            bitmap.compress(Bitmap.CompressFormat.JPEG, JPEG_QUALITY, outputStream)
        }
        val tEncode = System.currentTimeMillis()

        writeExif(context, imageUri, metadata)
        val tExif = System.currentTimeMillis()

        contentValues.clear()
        contentValues.put(MediaStore.MediaColumns.IS_PENDING, 0)
        context.contentResolver.update(imageUri, contentValues, null, null)

        if (BuildConfig.DEBUG) {
            Log.d(
                TAG,
                "[PERF_STILL] total=${tExif - shutterStart}ms readback=${readbackTime}ms " +
                    "bitmap=${bitmapTime}ms encode=${tEncode - tStart}ms exif=${tExif - tEncode}ms"
            )
        }
    } catch (e: Exception) {
        Log.e(TAG, "capture Failed to save image or metadata", e)
        context.mainExecutor.execute {
            Toast.makeText(context, "Failed to save image", Toast.LENGTH_SHORT).show()
        }
    }
}

private fun writeExif(context: Context, imageUri: Uri, metadata: CaptureMetadata) {
    context.contentResolver.openFileDescriptor(imageUri, "rw")?.use { pfd ->
        val exif = ExifInterface(pfd.fileDescriptor)
        val exposureTimeSeconds =
            if (metadata.exposureTimeNs > 0) metadata.exposureTimeNs / NS_PER_SECOND else 0.0

        Log.d(
            TAG,
            "Writing EXIF: ISO=${metadata.iso}, Exp=${exposureTimeSeconds}s, Focal=${metadata.focalLength}, " +
                "Aperture=${metadata.aperture}, Location=${metadata.location}"
        )

        exif.setAttribute(ExifInterface.TAG_MAKE, metadata.make)
        exif.setAttribute(ExifInterface.TAG_MODEL, metadata.model)
        exif.setAttribute(ExifInterface.TAG_SOFTWARE, CAMERA_APP_NAME)
        exif.setAttribute(ExifInterface.TAG_ARTIST, CAMERA_APP_NAME)
        exif.setAttribute(ExifInterface.TAG_FOCAL_LENGTH, "${(metadata.focalLength * 1000).toInt()}/1000")
        exif.setAttribute(ExifInterface.TAG_F_NUMBER, metadata.aperture.toString())
        exif.setAttribute(ExifInterface.TAG_PHOTOGRAPHIC_SENSITIVITY, metadata.iso.toString())
        exif.setAttribute(ExifInterface.TAG_EXPOSURE_TIME, exposureTimeSeconds.toString())

        metadata.location?.let { location ->
            exif.setLatLong(location.latitude, location.longitude)
            exif.setGpsInfo(location)
        }
        exif.saveAttributes()
    }
}

@Composable
fun BuildTimerText() {
    var buildTimeText by remember { mutableStateOf("Built: calculating...") }

    LaunchedEffect(Unit) {
        while (true) {
            val minutesSinceBuild = (System.currentTimeMillis() - BuildConfig.BUILD_TIME) / (1000 * 60)
            buildTimeText = if (minutesSinceBuild < 1) {
                "Built: just now"
            } else {
                "Built: $minutesSinceBuild min ago"
            }
            delay(60_000)
        }
    }

    Surface(
        color = Color.Black.copy(alpha = 0.5f),
        shape = CircleShape
    ) {
        Text(
            text = buildTimeText,
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
            color = Color.White,
            style = MaterialTheme.typography.labelMedium
        )
    }
}

fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "0s"
    if (exposureTimeNs < SLOW_SHUTTER_THRESHOLD_NS) {
        return "1/${(NS_PER_SECOND / exposureTimeNs).roundToInt()}s"
    }

    val seconds = exposureTimeNs / NS_PER_SECOND
    val text = if (seconds % 1.0 == 0.0) {
        seconds.toInt().toString()
    } else {
        String.format("%.2f", seconds).trimEnd('0').trimEnd('.')
    }
    return "${text}s"
}

fun Context.findActivity(): ComponentActivity? = when (this) {
    is ComponentActivity -> this
    is ContextWrapper -> baseContext.findActivity()
    else -> null
}

